import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "command-sample",
  name: "命令示例",
  version: "1.0.0",
  onLoad(ctx) {
    // 注册 command：name=upper，将参数数组第一个元素转换为大写
    ctx.register({
      kind: "command",
      command: {
        name: "upper",
        description: "将参数数组第一个元素转换为大写",
        handler: async (args: unknown[]) => {
          const first = Array.isArray(args) ? args[0] : undefined;
          const upper = typeof first === "string" ? first.toUpperCase() : String(first);
          return { ok: true, data: { command: upper } };
        },
      },
    });

    // 同时注册一个 tool 包装，便于通过宿主工具入口调用该命令
    ctx.register({
      kind: "tool",
      tool: {
        name: "command-sample_upper",
        version: "1.0.0",
        description: "调用 command-sample 的 upper 命令：将参数数组第一个元素转换为大写",
        permissions: { capabilities: [{ kind: "command", name: "upper" }] },
        sideEffect: "pure",
        parameters: {
          type: "object",
          properties: {
            args: {
              type: "array",
              items: { type: "string" },
              description: "参数数组，第一个元素将被转换为大写",
            },
          },
          required: ["args"],
        },
        outputSchema: {
          type: "object",
          properties: {
            ok: { type: "boolean" },
            data: {
              type: "object",
              properties: { command: { type: "string" } },
            },
          },
        },
        async handler(args: { args?: unknown[] }, tctx) {
          const list = Array.isArray(args?.args) ? args!.args! : [];
          const res = await tctx.invoke("command", "upper", list);
          return res;
        },
      },
    });
  },
};

export default plugin;

